:root {
  --ocean: #0077b6;
  --ocean-dark: #023e8a;
  --ocean-light: #90e0ef;
  --ocean-pale: #caf0f8;
  --sand: #f4a261;
  --sand-light: #fde8d0;
  --green: #2d6a4f;
  --green-light: #d8f3dc;
  --yellow: #b5830a;
  --yellow-light: #fff3cd;
  --alert-bg: #fff1e6;
  --alert-text: #9c4221;
  --text-dark: #1a1a2e;
  --text-mid: #4a4a6a;
  --text-light: #8888aa;
  --card-bg: #ffffff;
  --border: #e0e8f0;
  --dot-filled: #0077b6;
  --dot-empty: #dde6f0;
}

body {
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 100vh;
  margin: 0;
  padding: 20px;
  box-sizing: border-box;
}

.surf-card {
  background: var(--card-bg);
  border: 2px solid var(--border);
  border-radius: 16px;
  padding: 20px;
  width: 480px;
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.surf-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.location {
  display: flex;
  align-items: center;
  gap: 8px;
}

.location-dot {
  width: 10px;
  height: 10px;
  background: var(--ocean);
  border-radius: 50%;
  display: inline-block;
}

.location-name {
  font-size: 18px;
  font-weight: 700;
  color: var(--text-dark);
}

.surf-date {
  font-size: 13px;
  font-weight: 500;
  color: var(--text-light);
  background: var(--ocean-pale);
  padding: 4px 10px;
  border-radius: 20px;
}

.conditions-row {
  display: flex;
  align-items: center;
  background: var(--ocean-pale);
  border-radius: 12px;
  padding: 14px 0;
}

.wave-stat {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2px;
}

.stat-value {
  font-size: 26px;
  font-weight: 800;
  color: var(--ocean-dark);
  line-height: 1;
}

.stat-unit {
  font-size: 12px;
  font-weight: 600;
  color: var(--ocean);
  text-transform: uppercase;
}

.stat-label {
  font-size: 11px;
  color: var(--text-mid);
  margin-top: 2px;
}

.divider-v {
  width: 1px;
  height: 48px;
  background: var(--ocean-light);
}

.rating-bar {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 14px;
  background: var(--sand-light);
  border-radius: 10px;
  border: 1px solid var(--sand);
}

.rating-label {
  font-size: 13px;
  font-weight: 600;
  color: var(--text-mid);
  flex: 1;
}

.rating-dots {
  display: flex;
  gap: 5px;
}

.dot {
  width: 12px;
  height: 12px;
  border-radius: 50%;
  background: var(--dot-empty);
  display: inline-block;
}

.dot.filled {
  background: var(--dot-filled);
}

.rating-text {
  font-size: 13px;
  font-weight: 700;
  color: var(--ocean-dark);
}

.sessions-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 8px;
}

.session {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 5px;
  padding: 10px 6px;
  border: 1px solid var(--border);
  border-radius: 10px;
}

.session-time {
  font-size: 11px;
  font-weight: 600;
  color: var(--text-light);
  text-transform: uppercase;
  letter-spacing: 0.03em;
}

.session-badge {
  font-size: 12px;
  font-weight: 700;
  padding: 2px 8px;
  border-radius: 20px;
}

.session-badge.best {
  background: var(--green-light);
  color: var(--green);
}

.session-badge.good {
  background: var(--ocean-pale);
  color: var(--ocean-dark);
}

.session-badge.ok {
  background: var(--yellow-light);
  color: var(--yellow);
}

.session-tide {
  font-size: 11px;
  color: var(--text-mid);
}

.surf-footer {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 10px 14px;
  background: var(--alert-bg);
  border-radius: 10px;
  border-left: 4px solid var(--sand);
}

.alert-icon {
  font-size: 14px;
  color: var(--sand);
}

.alert-text {
  font-size: 12px;
  font-weight: 500;
  color: var(--alert-text);
}
